:root {
    --color-primary: #111827; /* Tailwind Gray 900 */
    --color-primary-light: #374151; /* Tailwind Gray 700 */
    --color-secondary: #4f46e5; /* Tailwind Indigo 600 */
    --color-secondary-hover: #4338ca; /* Tailwind Indigo 700 */
    --color-bg: #ffffff;
    --color-bg-alt: #f9fafb; /* Tailwind Gray 50 */
    --color-bg-accent: #f3f4f6; /* Tailwind Gray 100 */
    --color-text: #1f2937; /* Tailwind Gray 800 */
    --color-text-muted: #6b7280; /* Tailwind Gray 500 */
    --color-border: #e5e7eb; /* Tailwind Gray 200 */
    --color-danger: #ef4444;

    --font-sans: 'Inter', system-ui, -apple-system, sans-serif;

    --spacing-xs: 0.25rem;
    --spacing-sm: 0.5rem;
    --spacing-md: 1rem;
    --spacing-lg: 1.5rem;
    --spacing-xl: 2rem;
    --spacing-2xl: 3rem;
    --spacing-3xl: 4rem;

    --radius-sm: 0.25rem;
    --radius-md: 0.375rem;
    --radius-lg: 0.5rem;

    --transition-fast: 0.15s ease-in-out;
    --transition-normal: 0.3s ease-in-out;

    --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
    --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
    --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
}

/* Base Reset */
*, *::before, *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

html {
    font-size: 16px;
    scroll-behavior: smooth;
}

body {
    font-family: var(--font-sans);
    color: var(--color-text);
    background-color: var(--color-bg);
    line-height: 1.5;
    -webkit-font-smoothing: antialiased;
}

a {
    color: inherit;
    text-decoration: none;
    transition: color var(--transition-fast);
}

img, svg {
    display: block;
    max-width: 100%;
}

button, input {
    font-family: inherit;
    border: none;
    background: none;
}

ul {
    list-style: none;
}

/* Utility Classes */
.container {
    width: 100%;
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 var(--spacing-lg);
}

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border-width: 0;
}

.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--color-secondary);
    color: white;
    padding: var(--spacing-sm) var(--spacing-md);
    z-index: 100;
    transition: top var(--transition-fast);
}

.skip-link:focus {
    top: 0;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
    color: var(--color-primary);
    font-weight: 600;
    line-height: 1.2;
}

h1 {
    font-size: clamp(2.5rem, 5vw, 4rem);
    letter-spacing: -0.025em;
}

h2 {
    font-size: clamp(2rem, 3vw, 2.5rem);
    letter-spacing: -0.025em;
    margin-bottom: var(--spacing-xl);
}

h3 {
    font-size: 1.25rem;
}

/* Focus Styles for Accessibility */
:focus-visible {
    outline: 2px solid var(--color-secondary);
    outline-offset: 2px;
}

/* Buttons */
.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 0.75rem 1.5rem;
    font-weight: 500;
    border-radius: var(--radius-md);
    cursor: pointer;
    transition: all var(--transition-fast);
    text-align: center;
}

.btn-primary {
    background-color: var(--color-primary);
    color: white;
}

.btn-primary:hover, .btn-primary:focus {
    background-color: var(--color-primary-light);
}

.btn-outline {
    background-color: transparent;
    color: var(--color-primary);
    border: 1px solid var(--color-border);
}

.btn-outline:hover, .btn-outline:focus {
    border-color: var(--color-primary);
    background-color: var(--color-bg-accent);
}

.btn-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 2.5rem;
    height: 2.5rem;
    border-radius: 50%;
    color: var(--color-text-muted);
    transition: all var(--transition-fast);
    cursor: pointer;
    background-color: white;
    box-shadow: var(--shadow-sm);
}

.btn-icon:hover, .btn-icon:focus {
    color: var(--color-primary);
    box-shadow: var(--shadow-md);
}

/* Header & Nav */
.site-header {
    border-bottom: 1px solid var(--color-border);
    position: sticky;
    top: 0;
    background-color: rgba(255, 255, 255, 0.95);
    backdrop-filter: blur(8px);
    z-index: 50;
}

.header-container {
    display: flex;
    align-items: center;
    justify-content: space-between;
    height: 4.5rem;
    padding: 0 var(--spacing-lg);
    max-width: 1400px;
    margin: 0 auto;
}

.logo {
    font-weight: 700;
    font-size: 1.5rem;
    letter-spacing: 0.05em;
}

.main-nav {
    display: flex;
    align-items: center;
}

.nav-list {
    display: flex;
    gap: var(--spacing-xl);
}

.nav-list a {
    font-weight: 500;
    color: var(--color-text-muted);
}

.nav-list a:hover, .nav-list a[aria-current="page"] {
    color: var(--color-primary);
}

.menu-toggle {
    display: none;
    padding: var(--spacing-sm);
    color: var(--color-primary);
    cursor: pointer;
}

.header-actions {
    display: flex;
    align-items: center;
    gap: var(--spacing-md);
}

.action-btn {
    color: var(--color-primary);
    padding: var(--spacing-sm);
    cursor: pointer;
    position: relative;
}

.cart-count {
    position: absolute;
    top: 0;
    right: 0;
    background-color: var(--color-secondary);
    color: white;
    font-size: 0.65rem;
    font-weight: 700;
    width: 1.25rem;
    height: 1.25rem;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
}

/* Hero Section */
.hero {
    display: grid;
    grid-template-columns: 1fr;
    min-height: calc(100vh - 4.5rem);
    background-color: var(--color-bg-alt);
    position: relative;
    overflow: hidden;
}

.hero-content {
    display: flex;
    flex-direction: column;
    justify-content: center;
    padding: var(--spacing-3xl) var(--spacing-lg);
    max-width: 600px;
    z-index: 10;
}

.hero p {
    font-size: 1.25rem;
    color: var(--color-text-muted);
    margin: var(--spacing-lg) 0 var(--spacing-xl);
}

.hero-image {
    position: absolute;
    top: 0;
    right: 0;
    bottom: 0;
    width: 50%;
    background-image: url('https://images.unsplash.com/photo-1441984904996-e0b6ba687e04?ixlib=rb-4.0.3&auto=format&fit=crop&w=1600&q=80');
    background-size: cover;
    background-position: center;
}

/* Sections General */
section {
    padding: var(--spacing-3xl) 0;
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    margin-bottom: var(--spacing-xl);
}

.section-header h2 {
    margin-bottom: 0;
}

.view-all {
    font-weight: 500;
    color: var(--color-secondary);
    display: flex;
    align-items: center;
    gap: var(--spacing-xs);
}

.view-all:hover {
    color: var(--color-secondary-hover);
}

/* Featured Products */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: var(--spacing-xl);
}

.product-card {
    display: flex;
    flex-direction: column;
    group: hover;
}

.product-image-container {
    position: relative;
    aspect-ratio: 3/4;
    overflow: hidden;
    background-color: var(--color-bg-accent);
    border-radius: var(--radius-md);
    margin-bottom: var(--spacing-md);
}

.product-image {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform var(--transition-normal);
}

.product-card:hover .product-image {
    transform: scale(1.05);
}

.add-to-favorites {
    position: absolute;
    top: var(--spacing-md);
    right: var(--spacing-md);
    opacity: 0;
    transform: translateY(-10px);
}

.product-card:hover .add-to-favorites,
.add-to-favorites:focus-visible {
    opacity: 1;
    transform: translateY(0);
}

.product-info {
    display: flex;
    flex-direction: column;
    flex-grow: 1;
}

.product-title {
    font-size: 1rem;
    margin-bottom: var(--spacing-xs);
}

.product-title a::after {
    content: "";
    position: absolute;
    inset: 0;
}

.product-category {
    font-size: 0.875rem;
    color: var(--color-text-muted);
    margin-bottom: var(--spacing-sm);
}

.product-price {
    font-weight: 600;
    color: var(--color-primary);
    margin-bottom: var(--spacing-md);
}

.add-to-cart {
    margin-top: auto;
    width: 100%;
    position: relative;
    z-index: 2;
}

/* Deals Section */
.deals-section {
    background-color: var(--color-bg-alt);
}

.deals-banner {
    background-image: linear-gradient(rgba(0,0,0,0.4), rgba(0,0,0,0.4)), url('https://images.unsplash.com/photo-1607082348824-0a96f2a4b9da?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80');
    background-size: cover;
    background-position: center;
    border-radius: var(--radius-lg);
    padding: var(--spacing-3xl) var(--spacing-xl);
    color: white;
    text-align: center;
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 400px;
}

.deals-content {
    max-width: 500px;
}

.deals-content h2 {
    color: white;
    margin: var(--spacing-md) 0;
}

.deals-content p {
    font-size: 1.125rem;
    margin-bottom: var(--spacing-xl);
    opacity: 0.9;
}

.badge {
    display: inline-block;
    padding: var(--spacing-xs) var(--spacing-sm);
    background-color: var(--color-danger);
    color: white;
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    border-radius: var(--radius-sm);
}

/* Editorial */
.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: var(--spacing-2xl);
}

.editorial-card {
    display: flex;
    flex-direction: column;
}

.editorial-image {
    width: 100%;
    aspect-ratio: 16/9;
    object-fit: cover;
    border-radius: var(--radius-md);
    margin-bottom: var(--spacing-md);
}

.editorial-meta {
    display: flex;
    align-items: center;
    gap: var(--spacing-md);
    font-size: 0.875rem;
    margin-bottom: var(--spacing-sm);
}

.editorial-category {
    font-weight: 600;
    color: var(--color-secondary);
}

.editorial-date {
    color: var(--color-text-muted);
}

.editorial-title {
    font-size: 1.5rem;
    margin-bottom: var(--spacing-sm);
}

.editorial-title a:hover {
    text-decoration: underline;
    text-underline-offset: 4px;
}

.editorial-excerpt {
    color: var(--color-text-muted);
    margin-bottom: var(--spacing-md);
    flex-grow: 1;
}

.read-more {
    font-weight: 500;
    color: var(--color-primary);
    text-decoration: underline;
    text-underline-offset: 4px;
}

.read-more:hover {
    color: var(--color-secondary);
}

/* Newsletter */
.newsletter-section {
    border-top: 1px solid var(--color-border);
    padding: var(--spacing-3xl) 0;
}

.newsletter-container {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: var(--spacing-xl);
}

.newsletter-content {
    flex: 1;
    min-width: 300px;
}

.newsletter-content h2 {
    margin-bottom: var(--spacing-sm);
}

.newsletter-content p {
    color: var(--color-text-muted);
}

.newsletter-form {
    flex: 1;
    min-width: 300px;
    max-width: 500px;
}

.form-group {
    display: flex;
    gap: var(--spacing-sm);
}

.newsletter-form input {
    flex-grow: 1;
    padding: 0.75rem 1rem;
    border: 1px solid var(--color-border);
    border-radius: var(--radius-md);
    background-color: var(--color-bg-alt);
}

.newsletter-form input:focus-visible {
    outline: 2px solid var(--color-secondary);
    border-color: var(--color-secondary);
}

/* Footer */
.site-footer {
    background-color: var(--color-primary);
    color: white;
    padding-top: var(--spacing-3xl);
}

.footer-grid {
    display: grid;
    grid-template-columns: 2fr repeat(3, 1fr);
    gap: var(--spacing-2xl);
    margin-bottom: var(--spacing-3xl);
}

.footer-brand p {
    color: #9ca3af; /* Tailwind Gray 400 */
    margin: var(--spacing-md) 0;
}

.footer-logo {
    font-size: 1.5rem;
    font-weight: 700;
    letter-spacing: 0.05em;
}

.social-links {
    display: flex;
    gap: var(--spacing-md);
    margin-top: var(--spacing-lg);
}

.social-links a {
    color: #9ca3af;
}

.social-links a:hover, .social-links a:focus-visible {
    color: white;
}

.footer-heading {
    color: white;
    font-size: 1rem;
    margin-bottom: var(--spacing-lg);
}

.footer-nav ul {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-sm);
}

.footer-nav a {
    color: #9ca3af;
    font-size: 0.875rem;
}

.footer-nav a:hover, .footer-nav a:focus-visible {
    color: white;
}

.footer-bottom {
    border-top: 1px solid #374151; /* Tailwind Gray 700 */
    padding: var(--spacing-md) 0;
    text-align: center;
    color: #9ca3af;
    font-size: 0.875rem;
}

/* Responsive Design */
@media (max-width: 1024px) {
    .hero {
        grid-template-columns: 1fr;
    }

    .hero-image {
        position: relative;
        width: 100%;
        height: 40vh;
        order: -1;
    }

    .hero-content {
        padding: var(--spacing-2xl) var(--spacing-lg);
        max-width: 100%;
        text-align: center;
        align-items: center;
    }

    .footer-grid {
        grid-template-columns: 1fr 1fr;
    }
}

@media (max-width: 768px) {
    .nav-list {
        display: none;
        position: absolute;
        top: 100%;
        left: 0;
        right: 0;
        background-color: white;
        flex-direction: column;
        padding: var(--spacing-lg);
        border-bottom: 1px solid var(--color-border);
        box-shadow: var(--shadow-md);
        gap: var(--spacing-md);
    }

    .nav-list.active {
        display: flex;
    }

    .menu-toggle {
        display: block;
    }

    .footer-grid {
        grid-template-columns: 1fr;
    }

    .newsletter-container {
        flex-direction: column;
        align-items: flex-start;
    }

    .form-group {
        flex-direction: column;
    }
}

/* Accessibility: Reduced Motion */
@media (prefers-reduced-motion: reduce) {
    *, *::before, *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}

/* Accessibility: Forced Colors */
@media (forced-colors: active) {
    .btn-primary {
        border: 1px solid ButtonText;
    }
    .badge {
        border: 1px solid ButtonText;
    }
}
