    // Mobile Menu Toggle
    const menuToggle = document.querySelector('.menu-toggle');
    const navList = document.getElementById('nav-list');

    if (menuToggle && navList) {
        menuToggle.addEventListener('click', () => {
            const isExpanded = menuToggle.getAttribute('aria-expanded') === 'true';
            menuToggle.setAttribute('aria-expanded', !isExpanded);
            navList.classList.toggle('active');
        });
    }

    // Cart Functionality
    const addToCartBtns = document.querySelectorAll('.add-to-cart');
    const cartCountEl = document.querySelector('.cart-count');
    let cartCount = 0;

    addToCartBtns.forEach(btn => {
        btn.addEventListener('click', (e) => {
            // Prevent navigating if the button is within a link context 
            e.preventDefault();
            e.stopPropagation();

            // Increment cart
            cartCount++;

            // Update UI
            if (cartCountEl) {
                cartCountEl.textContent = cartCount;

                // Optional: Provide screen reader feedback that item was added
                const srAnnouncement = document.createElement('div');
                srAnnouncement.setAttribute('aria-live', 'polite');
                srAnnouncement.classList.add('sr-only');
                srAnnouncement.textContent = 'Item added to cart';
                document.body.appendChild(srAnnouncement);

                // Visual feedback on button
                const originalText = btn.textContent;
                btn.textContent = 'Added!';
                btn.classList.add('btn-primary');
                btn.classList.remove('btn-outline');

                setTimeout(() => {
                    btn.textContent = originalText;
                    btn.classList.remove('btn-primary');
                    btn.classList.add('btn-outline');
                    // Clean up SR announcement
                    setTimeout(() => {
                        if (document.body.contains(srAnnouncement)) {
                            document.body.removeChild(srAnnouncement);
                        }
                    }, 1000);
                }, 2000);
            }
        });
    });

    // Favorite Button Functionality (Toggle)
    const favoriteBtns = document.querySelectorAll('.add-to-favorites');

    favoriteBtns.forEach(btn => {
        btn.addEventListener('click', (e) => {
            e.preventDefault();
            e.stopPropagation();

            const svg = btn.querySelector('svg');
            const isFavorite = btn.getAttribute('aria-pressed') === 'true';

            if (isFavorite) {
                btn.setAttribute('aria-pressed', 'false');
                svg.setAttribute('fill', 'none');
                btn.setAttribute('aria-label', 'Add to favorites');
            } else {
                btn.setAttribute('aria-pressed', 'true');
                svg.setAttribute('fill', 'currentColor');
                svg.style.color = 'var(--color-danger)';
                btn.setAttribute('aria-label', 'Remove from favorites');
            }
        });
    });
});
