+                svg.setAttribute('fill', 'none');
+                btn.setAttribute('aria-label', 'Add to favorites');
+            } else {
+                btn.setAttribute('aria-pressed', 'true');
+                svg.setAttribute('fill', 'currentColor');
+                svg.style.color = 'var(--color-danger)';
